import { AlertCircle, CheckCircle, Loader, MessageSquare, Send } from "lucide-react";
import { useEffect, useState } from "react";

const API_URL = import.meta.env.VITE_API_URL || "https://queueless-india-a2ju.onrender.com/api";

export default function Complaints() {
  const [complaints, setComplaints] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [userRole, setUserRole] = useState("");
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    category: "Service Quality",
    severity: "Medium",
    location: "Hospital",
    submitterName: "",
    submitterPhone: "",
  });
  const [filter, setFilter] = useState({ status: "Open" });

  useEffect(() => {
    const session = JSON.parse(localStorage.getItem("queueless_session") || "{}");
    setUserRole(session.role || "");
    loadComplaints();
  }, [filter]);

  const loadComplaints = async () => {
    try {
      setLoading(true);
      const session = JSON.parse(localStorage.getItem("queueless_session") || "{}");

      if (!["ADMIN", "HOSPITAL", "GOVERNMENT OFFICE"].includes(session.role)) {
        setComplaints([]);
        return;
      }

      const query = new URLSearchParams(filter);
      const response = await fetch(`${API_URL}/complaints?${query}`, {
        headers: {
          Authorization: `Bearer ${session.token}`,
        },
      });

      if (response.ok) {
        const data = await response.json();
        setComplaints(data.complaints || []);
      }
    } catch (error) {
      console.error("Error loading complaints:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitComplaint = async (e) => {
    e.preventDefault();
    try {
      setLoading(true);

      if (!formData.title.trim() || !formData.description.trim()) {
        alert("Please fill in all required fields");
        return;
      }

      const response = await fetch(`${API_URL}/complaints`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        alert("Complaint submitted successfully!");
        setFormData({
          title: "",
          description: "",
          category: "Service Quality",
          severity: "Medium",
          location: "Hospital",
          submitterName: "",
          submitterPhone: "",
        });
        setShowForm(false);
        loadComplaints();
      } else {
        alert("Failed to submit complaint");
      }
    } catch (error) {
      alert("Error submitting complaint: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const getSeverityColor = (severity) => {
    switch (severity) {
      case "Critical":
        return "bg-red-100 text-red-700 border-red-300";
      case "High":
        return "bg-orange-100 text-orange-700 border-orange-300";
      case "Medium":
        return "bg-yellow-100 text-yellow-700 border-yellow-300";
      default:
        return "bg-green-100 text-green-700 border-green-300";
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case "Resolved":
        return <CheckCircle className="h-5 w-5 text-green-600" />;
      case "In Progress":
        return <Loader className="h-5 w-5 text-blue-600 animate-spin" />;
      default:
        return <AlertCircle className="h-5 w-5 text-amber-600" />;
    }
  };

  return (
    <main className="min-h-screen bg-gradient-to-b from-slate-50 to-slate-100 px-4 py-8">
      <div className="mx-auto max-w-4xl">
        <div className="mb-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <MessageSquare className="h-8 w-8 text-blue-700" />
            <h1 className="text-3xl font-bold text-slate-900">Complaints & Feedback</h1>
          </div>
          <button
            onClick={() => setShowForm(!showForm)}
            className="rounded-xl bg-blue-700 px-4 py-2 font-semibold text-white transition hover:bg-blue-800"
          >
            {showForm ? "Cancel" : "Submit Complaint"}
          </button>
        </div>

        {showForm && (
          <form
            onSubmit={handleSubmitComplaint}
            className="mb-8 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"
          >
            <h2 className="mb-4 text-xl font-bold text-slate-900">
              Submit a Complaint
            </h2>

            <div className="space-y-4">
              <input
                type="text"
                placeholder="Your Name"
                value={formData.submitterName}
                onChange={(e) =>
                  setFormData({ ...formData, submitterName: e.target.value })
                }
                className="w-full rounded-xl border border-slate-300 px-4 py-2"
                required
              />

              <input
                type="tel"
                placeholder="Your Phone Number"
                value={formData.submitterPhone}
                onChange={(e) =>
                  setFormData({ ...formData, submitterPhone: e.target.value })
                }
                className="w-full rounded-xl border border-slate-300 px-4 py-2"
                required
              />

              <div className="grid gap-4 md:grid-cols-2">
                <select
                  value={formData.location}
                  onChange={(e) =>
                    setFormData({ ...formData, location: e.target.value })
                  }
                  className="rounded-xl border border-slate-300 px-4 py-2"
                >
                  <option value="Hospital">Hospital</option>
                  <option value="Government Office">Government Office</option>
                </select>

                <select
                  value={formData.category}
                  onChange={(e) =>
                    setFormData({ ...formData, category: e.target.value })
                  }
                  className="rounded-xl border border-slate-300 px-4 py-2"
                >
                  <option value="Service Quality">Service Quality</option>
                  <option value="Staff Behavior">Staff Behavior</option>
                  <option value="Wait Time">Wait Time</option>
                  <option value="Facilities">Facilities</option>
                  <option value="Other">Other</option>
                </select>
              </div>

              <input
                type="text"
                placeholder="Complaint Title"
                value={formData.title}
                onChange={(e) =>
                  setFormData({ ...formData, title: e.target.value })
                }
                className="w-full rounded-xl border border-slate-300 px-4 py-2"
                required
              />

              <textarea
                placeholder="Describe your complaint in detail..."
                value={formData.description}
                onChange={(e) =>
                  setFormData({ ...formData, description: e.target.value })
                }
                className="min-h-24 w-full rounded-xl border border-slate-300 px-4 py-2"
                required
              />

              <select
                value={formData.severity}
                onChange={(e) =>
                  setFormData({ ...formData, severity: e.target.value })
                }
                className="rounded-xl border border-slate-300 px-4 py-2"
              >
                <option value="Low">Low</option>
                <option value="Medium">Medium</option>
                <option value="High">High</option>
                <option value="Critical">Critical</option>
              </select>

              <button
                type="submit"
                disabled={loading}
                className="flex w-full items-center justify-center gap-2 rounded-xl bg-green-700 px-4 py-2 font-semibold text-white transition hover:bg-green-800 disabled:opacity-50"
              >
                <Send className="h-4 w-4" />
                {loading ? "Submitting..." : "Submit Complaint"}
              </button>
            </div>
          </form>
        )}

        {["ADMIN", "HOSPITAL", "GOVERNMENT OFFICE"].includes(userRole) && (
          <div className="mb-6 flex gap-2 overflow-x-auto">
            {["Open", "In Progress", "Resolved", "Closed"].map((status) => (
              <button
                key={status}
                onClick={() => setFilter({ ...filter, status })}
                className={`whitespace-nowrap rounded-full px-4 py-2 font-semibold transition ${
                  filter.status === status
                    ? "bg-blue-700 text-white"
                    : "bg-slate-200 text-slate-700 hover:bg-slate-300"
                }`}
              >
                {status}
              </button>
            ))}
          </div>
        )}

        <div className="space-y-4">
          {loading ? (
            <p className="text-center text-slate-600">Loading complaints...</p>
          ) : complaints.length === 0 ? (
            <p className="rounded-2xl bg-white p-6 text-center text-slate-500">
              {userRole ? "No complaints found." : "Login to view complaints."}
            </p>
          ) : (
            complaints.map((complaint) => (
              <div
                key={complaint._id}
                className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm transition hover:shadow-md"
              >
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      {getStatusIcon(complaint.status)}
                      <h3 className="font-bold text-slate-900">
                        {complaint.title}
                      </h3>
                      <span
                        className={`rounded-full border px-2 py-1 text-xs font-semibold ${getSeverityColor(
                          complaint.severity
                        )}`}
                      >
                        {complaint.severity}
                      </span>
                    </div>
                    <p className="mt-2 text-sm text-slate-600">
                      {complaint.description}
                    </p>
                    <div className="mt-3 flex flex-wrap gap-2">
                      <span className="rounded-full bg-slate-100 px-3 py-1 text-xs text-slate-700">
                        {complaint.category}
                      </span>
                      <span className="rounded-full bg-slate-100 px-3 py-1 text-xs text-slate-700">
                        Status: {complaint.status}
                      </span>
                      {complaint.hospital && (
                        <span className="rounded-full bg-blue-100 px-3 py-1 text-xs text-blue-700">
                          {complaint.hospital.name}
                        </span>
                      )}
                      {complaint.governmentOffice && (
                        <span className="rounded-full bg-blue-100 px-3 py-1 text-xs text-blue-700">
                          {complaint.governmentOffice.name}
                        </span>
                      )}
                    </div>
                    {complaint.resolution && (
                      <div className="mt-3 rounded-lg bg-green-50 p-3 text-sm text-green-800">
                        <strong>Resolution:</strong> {complaint.resolution}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </main>
  );
}
